#include <stdio.h>
int inv26(int x){x=(x%26+26)%26;for(int i=1;i<26;i++)if(x*i%26==1)return i;return -1;}
int main(){int p[2][2],c[2][2];puts("Enter two plaintext column vectors as rows (x1 y1, x2 y2), then corresponding ciphertext vectors.");printf("Plaintext matrix rows: ");scanf("%d%d%d%d",&p[0][0],&p[0][1],&p[1][0],&p[1][1]);printf("Ciphertext matrix rows: ");scanf("%d%d%d%d",&c[0][0],&c[0][1],&c[1][0],&c[1][1]);int d=(p[0][0]*p[1][1]-p[0][1]*p[1][0])%26;int di=inv26(d);if(di<0){puts("Plaintext matrix is not invertible mod 26; choose another pair.");return 0;}int ip[2][2]={{p[1][1]*di%26,(-p[0][1]*di%26+26)%26},{(-p[1][0]*di%26+26)%26,p[0][0]*di%26}};int k[2][2];for(int i=0;i<2;i++)for(int j=0;j<2;j++){k[i][j]=(c[i][0]*ip[0][j]+c[i][1]*ip[1][j])%26;}printf("Recovered Hill key: [%d %d; %d %d]\n",k[0][0],k[0][1],k[1][0],k[1][1]);return 0;}
